CREATE TABLE compliance_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),award_id UUID REFERENCES awards(id) ON DELETE CASCADE,application_id UUID REFERENCES applications(id) ON DELETE CASCADE,compliance_type VARCHAR(100) NOT NULL,authority VARCHAR(180),reference VARCHAR(120),status VARCHAR(40) NOT NULL DEFAULT 'PENDING',approved_date DATE,expiry_date DATE,renewal_due_date DATE,storage_key TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_compliance_due ON compliance_records(status,renewal_due_date);
CREATE TABLE declarations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,entity_type VARCHAR(80),entity_id UUID,declaration_type VARCHAR(100) NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'DECLARED',details TEXT,declared_at TIMESTAMPTZ NOT NULL DEFAULT now(),reviewed_by UUID REFERENCES users(id),reviewed_at TIMESTAMPTZ);
CREATE TABLE reports (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),award_id UUID NOT NULL REFERENCES awards(id) ON DELETE CASCADE,report_type VARCHAR(100) NOT NULL,period_start DATE,period_end DATE,due_date DATE NOT NULL,owner_user_id UUID REFERENCES users(id),status VARCHAR(40) NOT NULL DEFAULT 'NOT_STARTED',storage_key TEXT,submitted_at TIMESTAMPTZ,accepted_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE research_outputs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),award_id UUID NOT NULL REFERENCES awards(id) ON DELETE CASCADE,output_type VARCHAR(100) NOT NULL,title TEXT NOT NULL,citation_or_reference TEXT,url TEXT,output_date DATE,status VARCHAR(40) NOT NULL DEFAULT 'RECORDED',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE impact_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),award_id UUID NOT NULL REFERENCES awards(id) ON DELETE CASCADE,impact_type VARCHAR(100) NOT NULL,title VARCHAR(255) NOT NULL,description TEXT NOT NULL,evidence_storage_key TEXT,impact_date DATE,status VARCHAR(40) NOT NULL DEFAULT 'CLAIMED',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE closeout_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),award_id UUID NOT NULL REFERENCES awards(id) ON DELETE CASCADE,item_type VARCHAR(100) NOT NULL,title VARCHAR(255) NOT NULL,responsible_role VARCHAR(100),owner_user_id UUID REFERENCES users(id),status VARCHAR(40) NOT NULL DEFAULT 'PENDING',due_date DATE,completed_at TIMESTAMPTZ,evidence_storage_key TEXT);
CREATE TABLE system_settings (setting_key VARCHAR(180) PRIMARY KEY,setting_value TEXT,value_type VARCHAR(30) NOT NULL DEFAULT 'STRING',description TEXT,sensitive BOOLEAN NOT NULL DEFAULT FALSE,updated_by UUID REFERENCES users(id),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notification_rules (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),event_type VARCHAR(100) NOT NULL,days_before INTEGER,target_role_code VARCHAR(100),enabled BOOLEAN NOT NULL DEFAULT TRUE,escalation_days INTEGER,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE integration_registry (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),code VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,integration_type VARCHAR(80) NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'NOT_CONFIGURED',data_direction VARCHAR(40),owner_user_id UUID REFERENCES users(id),last_success_at TIMESTAMPTZ,last_failure_at TIMESTAMPTZ,last_failure_message TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE support_tickets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),reference VARCHAR(80) NOT NULL UNIQUE,requester_id UUID REFERENCES users(id),category VARCHAR(100) NOT NULL,priority VARCHAR(30) NOT NULL DEFAULT 'NORMAL',subject VARCHAR(255) NOT NULL,description TEXT NOT NULL,assigned_to UUID REFERENCES users(id),status VARCHAR(40) NOT NULL DEFAULT 'NEW',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),resolved_at TIMESTAMPTZ);
CREATE TABLE records_retention (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),entity_type VARCHAR(80) NOT NULL,entity_id UUID NOT NULL,retention_rule VARCHAR(180) NOT NULL,archive_date DATE,disposal_review_date DATE,hold BOOLEAN NOT NULL DEFAULT FALSE,hold_reason TEXT,status VARCHAR(40) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE access_reviews (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,role_id UUID NOT NULL REFERENCES roles(id) ON DELETE CASCADE,scope_type VARCHAR(64) NOT NULL DEFAULT 'INSTITUTION',scope_id UUID,reviewer_id UUID REFERENCES users(id),due_date DATE NOT NULL,decision VARCHAR(40),decision_note TEXT,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE system_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),event_type VARCHAR(100) NOT NULL,severity VARCHAR(30) NOT NULL,component VARCHAR(100),message TEXT NOT NULL,details JSONB,acknowledged_by UUID REFERENCES users(id),acknowledged_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_system_events_active ON system_events(severity,acknowledged_at,created_at DESC);
CREATE TABLE backup_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),backup_type VARCHAR(80) NOT NULL,started_at TIMESTAMPTZ NOT NULL,completed_at TIMESTAMPTZ,status VARCHAR(40) NOT NULL,size_bytes BIGINT,verification_status VARCHAR(40),storage_location TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE recovery_tests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),backup_run_id UUID REFERENCES backup_runs(id),tested_at TIMESTAMPTZ NOT NULL,status VARCHAR(40) NOT NULL,recovery_minutes INTEGER,notes TEXT,tested_by UUID REFERENCES users(id));
INSERT INTO notification_rules(event_type,days_before,target_role_code,escalation_days) VALUES ('OPPORTUNITY_DEADLINE',30,'RESEARCHER',7),('OPPORTUNITY_DEADLINE',14,'RESEARCHER',3),('OPPORTUNITY_DEADLINE',7,'RESEARCHER',1),('REPORT_DUE',30,'GRANTS_OFFICER',7),('REPORT_DUE',14,'RESEARCHER',3),('COMPLIANCE_RENEWAL',60,'GRANTS_OFFICER',14);
